   id: 'ship_gen_m_tugboat_01_a',
	  version: 0,
   name: '蝎尾狮',
   description: '在星门断连后的黑暗时期，Avarice | 贪婪 星系不得不依赖于因星门突然关闭而被困于此的各种飞船。贪婪公司在星门关闭后不久就倒闭了，有能力的科学家和工程师们便挺身而出，努力维持星系的稳定和可持续发展。他们首先建立了一个正常运作的船坞以维修和替换受损飞船，并且开始进行回收再生的先导研究以应对星系内逐渐枯竭的资源。后星门关闭时代的经济复苏进程随即被在新纪元800年发生的第一次星潮打乱。不过，这个毁灭性的恒星现象带来一个副产物，就是太阳能板的能量产出大幅提高，原有的生产模式也随之改变。清道夫在破潮砥柱——当时 Avarice | 贪婪 星系内仅存的空间站上发展起来的新经济模式利用了这种能源的充足性。由此，一种全新的、可自持的、基于回收再生的闭环经济体系逐渐建立起来，原有的飞船和空间站模块设计也得以进一步发展。对 Avarice | 贪婪 整个星系的重新殖民开始于新纪元818年，起因是洛斯维尔公司开始推广戍子和相应的戍子护盾发生器，它们可以保护空间站免受星潮的伤害。几年之后的新纪元825年，和 Windfall | 横财 的星门连接恢复，闭塞已久的清道夫势力得以和辛迪加的各成员势力贸易，但同时也成为了这些人的打劫对象。nn星门关闭后，被困于 Avarice | 贪婪 星系的Argon工程师迅速开发了第一款拖船，即蝎狮的前身，用于将小型舰船的残骸拖往空间站进行处理以最大化利用极为有限的资源。凭借这样的飞船，再加上他们开发的原始版废料处理和再生模块，这些人创立了一个小企业通过消耗大量能源以生产少量船体部件和电子黏土。新纪元800年发生的第一次星潮摧毁了该星系内的绝大部分飞船和空间站，而他们开发的这些蓝图也因此成为了整个清道夫势力的经济支柱，并且进一步发展为现在被广泛使用的空间站模块和搭载更强力引擎的蝎狮飞船。来自 Sacred Relic | 神圣遗迹 的信使无人机到达后，Avarice | 贪婪 的人们向其它断连的星系派出了他们自己的搭载着蓝图的信使无人机，希望能够帮到同样挣扎于资源短缺的不幸者。他们为此在破潮砥柱上设立了当地的约言联盟分部。星门于新纪元825年重连后，该分部随后便迁往了他们位于 Windfall | 横财 的空间站。',
