   id: 'ship_par_m_trans_container_03_a',
	  version: 0,
   name: '普罗米修斯',
   description: '星门的逐渐关闭以及随之而来的黑暗期导致曾被称为公爵的海盗的地下组织四分五裂。为了不被新崛起的当地强权打压，甚至被迫彻底偃旗息鼓，那些依然忠于公爵的海盗们也不得不转变行动做派。面对今后是否还能够作为一个组织而继续存在下去的挑战，大多数海盗选择呆在他们几十年来早已熟悉的领域：野蛮但可靠的安保团队。基于这种新旧兼有的外在形象，他们通过承运重要人员和物资以支撑家园重建和重新发展，为自身赢得了一定的声望。他们还经营安全保卫、商务咨询等各种合法到难以置信的业务。为了领导挣扎于孤立之中的各类群体，装备精良的武装力量是必不可少的。因此数十年来，公爵的海盗们设法改进了他们的技术以适应新领域的业务需求。nn普罗米修斯重型运输船是公爵的海盗武库中一种相对较新的装备，它总结了黑暗时期的所有教训，专门针对星门重连之后的新时期而开发。其船体原型是有名的Paranid采矿船普路托斯。尽管公爵的海盗以往的运输船都是为了图方便而直接用民用船改装的，但普罗米修斯的设计却是刻意为之而且极其低调。除非去专门仔细观察，否则看到它的人都只是简单地认为这不过是一艘为应对文明边缘星域潜藏危险做足准备的采矿船而已。然而如果再接近它一些，那么倒霉的路人或妄想撞大运的强盗马上就会发现这艘不起眼的采矿船事实上是一艘全副武装的海盗船，而且是为快速劫掠量身定制的。然而，从某种角度来看，深空采矿船的虚假身份似乎还有这么一丝真实信息：当成功实施一次空间站劫掠之后，这些飞船立马向附近星区外围驶去而不知所踪。',
