   description: '阿斯特丽德级游艇是洛斯维尔公司精神的具现化：修长且奢华到了过分的程度。欧若拉空间站上的设计师们不得不想方设法让这艘飞船满足甲方无数异想天开且经常自相矛盾的要求。因此，不管是最后的组装还是各个核心组件的生产，都必须手工完成。阿斯特丽德级至今仍是珍贵的限量款飞船。一系列专业车间和实验室被建立起来，专门供应制造阿斯特丽德级所需的各种花里胡哨的合成材料、用于豪华内饰的亮瞎眼的手工金属饰件以及拥有独特光泽的流线型外壳。这整个流程极为昂贵，使得阿斯特丽德级完全无法量产。这对有钱的收藏家来说是个好消息。欧若拉上的工程师们把之前开发诸如勒克斯等高速飞船积累的大量经验全部用于阿斯特丽德级引擎的研发。这艘耀眼的飞船坚固的货舱足以装载高度不稳定的玻色-爱因斯但冷凝态物质，据说它能够增加飞船抵御宇宙射线的能力同时提升其飞行性能。虽然这听起来就像伪科学的广告词，但是你不得不承认即使在最先进的豪华游艇中，阿斯特丽德级都快得令人发指。凭借这艘飞船，洛斯维尔公司的CEO甚至获得了"能同时身处几个地方"的名声。',
