	  version: 1,
   name: '多尼亚',
   description: '黑暗时期中的 Windfall | 横财 星系不仅孤立，而且因缺少船坞和有能力的工程师，因此造船能力低下。近四十年来，星系居民只能仰赖一支由因星门突然关闭而被困于此的各种飞船组成的舰队。星系里为数不多的工程师大部分精力都花在维护作业上，只能抽空试验自主设计的飞船。他们逐渐掌握了飞船制造工艺，并且开始利用手头的资源发挥创造力。他们的大部分作品都是把改装公共交通工具、退役飞船上拆下来的引擎和各种报废飞船上的零件七拼八凑到一起。直到新纪元821年和 Avarice | 贪婪 星系重新建立星门连接后，这些工程师们才最终放弃了他们手敲的破玩意转而着手开发适合量产的蓝图。有意思的是，这些蓝图仍然保留了过去那种杂乱无章的设计风格。nn当 Avarice | 贪婪 和 Windfall | 横财 于新纪元821年建立星门连接时，Windfall | 横财 的冰矿工们，即被称为固体冰联盟的工人集团，已经是星系中一支具有统治力量的势力。数十年来，他们团结在一起以艰难维持一支日益老化的采冰船队，这些飞船都是在黑暗期被困于当地星系的，其中包含了出自联合体的多种不同型号。为了确保在食品生产和采冰业务上的垄断，他们迫切地将星系内所有能找到的大型飞船都整合进自己的舰队，除了作为作业用飞船之外，也包括将它们拆解成零部件。星门重连之后，他们成了 Windfall | 横财 星系中唯一有能力充分利用大型飞船的势力，在面对新来者时，他们坚定不移地捍卫自己在采矿业务中的特权。nn当来自于 Avarice | 贪婪 星系的资源实现稳定供给并足以支撑飞船重新大规模生产之时，固体冰联盟开始建造一座造船厂。与此同时，他们开始研发自己的采冰船，多尼亚。他们充分利用了自身对于采冰船方面的丰富经验，并且对现在已经过时的联合体的相关飞船设计进行了细致分析。最终，多尼亚在新纪元824年设计完成，这是一型坚固且易于维护、可抵御小规模登船入侵的采矿船，它很快就取代了那些几乎无法使用并且早就过时的联合体的老型号。',
