	  version: 1,
   name: '巴巴罗萨',
   description: '黑暗时期中的 Windfall | 横财 星系不仅孤立，而且因缺少船坞和有能力的工程师，因此造船能力低下。近四十年来，星系居民只能仰赖一支由因星门突然关闭而被困于此的各种飞船组成的舰队。星系里为数不多的工程师大部分精力都花在维护作业上，只能抽空试验自主设计的飞船。他们逐渐掌握了飞船制造工艺，并且开始利用手头的资源发挥创造力。他们的大部分作品都是把改装公共交通工具、退役飞船上拆下来的引擎和各种报废飞船上的零件七拼八凑到一起。直到新纪元821年和 Avarice | 贪婪 星系重新建立星门连接后，这些工程师们才最终放弃了他们手敲的破玩意转而着手开发适合量产的蓝图。有意思的是，这些蓝图仍然保留了过去那种杂乱无章的设计风格。nn随着Avarice | 贪婪 和 Windfall | 横财 之间的星门于新纪元821年重新连接，一条重要却又充满竞争的贸易航线开启了。第一批运送食品至 Avarice | 贪婪 以及建筑材料至 Windfall | 横财 的飞船绝大部分都是黑暗期开始之前的遗留之物。由于海盗的骚扰，这些飞船很快就无法再使用了，取而代之的是由欧若拉赌场设计开发的信使飞船罗利。不久之后，约言联盟的船坞投入使用，开始生产联合体的运输船。与此同时，一个名为固体冰联盟的由冰矿工组成的工人集团经过多年努力，于新纪元823年开发完成了他们自己的货船，即巴巴罗萨。得益于高航速和相当数量的炮塔，固体冰联盟的船长们借助于自己的货船很快就垄断了 Windfall | 横财 与 Avarice | 贪婪 之间的贸易，他们不仅能够抵御海盗袭扰，甚至还攻击和劫掠其他货船来填满自己的货舱。nn在设计完巴巴罗萨之后，固体冰联盟的工程师们试图进一步研发一型驱逐舰，可是缺乏有关武器系统设计的必要知识。他们的尝试最终由于辛迪加的强行干预而不得不中止，后者并不信任已经初具武装的固体冰联盟，并且以内战作为威胁以逼迫其放弃进一步的武备建设。',
