   id: 'ship_pir_l_scrapper_01',
	  version: 1,
   name: '特乌塔',
   description: '在星门断连后的黑暗时期，Avarice | 贪婪 星系不得不依赖于因星门突然关闭而被困于此的各种飞船。贪婪公司在星门关闭后不久就倒闭了，有能力的科学家和工程师们便挺身而出，努力维持星系的稳定和可持续发展。他们首先建立了一个正常运作的船坞以维修和替换受损飞船，并且开始进行回收再生的先导研究以应对星系内逐渐枯竭的资源。后星门关闭时代的经济复苏进程随即被在新纪元800年发生的第一次星潮打乱。不过，这个毁灭性的恒星现象带来一个副产物，就是太阳能板的能量产出大幅提高，原有的生产模式也随之改变。清道夫在破潮砥柱——当时 Avarice | 贪婪 星系内仅存的空间站上发展起来的新经济模式利用了这种能源的充足性。由此，一种全新的、可自持的、基于回收再生的闭环经济体系逐渐建立起来，原有的飞船和空间站模块设计也得以进一步发展。对 Avarice | 贪婪 整个星系的重新殖民开始于新纪元818年，起因是洛斯维尔公司开始推广戍子和相应的戍子护盾发生器，它们可以保护空间站免受星潮的伤害。几年之后的新纪元825年，和 Windfall | 横财 的星门连接恢复，闭塞已久的清道夫势力得以和辛迪加的各成员势力贸易，但同时也成为了这些人的打劫对象。nn在建立起大规模的基于回收再生的经济体系以支持 Avarice | 贪婪 的殖民进程后，破潮砥柱的工程师们开始探索如何拆分和回收拖船和空间站模块无法处理的大型残骸。他们开发的残骸打包船，特乌塔，于新纪元822年首次亮相。类似于大型采矿飞船，该船会搜寻可回收资源并将其拆分，不过它不会把拆分后的资源运走，而是将其作为废料块弹出，等待拖船运送。',
