   description: '黑暗时期中的 Windfall | 横财 星系不仅孤立，而且因缺少船坞和有能力的工程师，因此造船能力低下。近四十年来，星系居民只能仰赖一支由因星门突然关闭而被困于此的各种飞船组成的舰队。星系里为数不多的工程师大部分精力都花在维护作业上，只能抽空试验自主设计的飞船。他们逐渐掌握了飞船制造工艺，并且开始利用手头的资源发挥创造力。他们的大部分作品都是把改装公共交通工具、退役飞船上拆下来的引擎和各种报废飞船上的零件七拼八凑到一起。直到新纪元821年和 Avarice | 贪婪 星系重新建立星门连接后，这些工程师们才最终放弃了他们手敲的破玩意转而着手开发适合量产的蓝图。有意思的是，这些蓝图仍然保留了过去那种杂乱无章的设计风格。nn在基德级战机面世之后，欧若拉赌场的工程师们着手自行设计一种性能超过所有现存型号的战斗机。在超过两年的时间里，经历一系列失败和挫折之后，他们于新纪元823年开发出了勒克斯。勒克斯装备了一具额外的引擎，因而在 Windfall | 横财 星系所有战斗机中同时为优秀的高速性和操纵性确立了新的标杆。只要办得到，所有人都会令手中的基德级机群退役，转而由勒克斯取代之。这导致大量廉价基德级飞船涌入市场，它们通常会被小一些的帮派购置，或者被拆解以换取原材料。廉价战机的大规模扩散引发了两个星系中海盗事件和军事冲突的增加，进而威胁辛迪加在近年来发动的一体化进程。',
