   description: '由深水钻探工业集团开发，长须鲸项目野心勃勃。经过多次失败，该公司最终于新纪元793年在 Kingdom End｜王国末路 造船厂完工并发布了他们第一款大型舰船。这款飞船堪堪能用，许多方面都有待改进。虽然深水钻探工业集团最终成功修复了所有设计缺陷并且通过召回升级已售出的飞船来挽回口碑，但是灾难性的首发还是让公司濒临破产。nn梅涅劳斯时代的飞船生产于新纪元785年到798年之间，是针对星门关闭而开发的第二批高度自动化的飞船。为了减小质量，这些飞船大部分空间填充空气，因此Boron船员需要穿戴防护服。梅涅劳斯的新内阁向中标政府合同的企业开放了多项Boron皇家防御军事研究所新研发的保密技术。采用这些技术设计的飞船不如第一批阿特柔斯时代的飞船结实，但是操控性更佳。',
