   description: '鼠海豚级采矿船的许多系统由深水钻探工业集团提供，该公司本来擅长深海钻探工程机械但是成功将其技术移植到了深空采矿作业。该船发布于新纪元784年，就在阿特柔斯女皇驾崩后不久，因此它是最后一款阿特柔斯时代的飞船。nn阿特柔斯时代的飞船是第一批针对新纪元778年的星门关闭事件而设计的飞船。出于对星系永久断连的担忧，不同于之前的泛用性设计思路，这些飞船的设计侧重于自动化作业。为了减小质量，这些飞船大部分空间填充空气，因此Boron船员需要穿戴防护服。阿特柔斯时代的飞船比梅涅劳斯时代的飞船更结实，但是操控性稍弱。nn为进一步应对的星门关闭事件，Boron女王国尝试通过加大财政投资和促进科研成果转化以加速新飞船的开发工作。在新开发的S级飞船框架获得成功后，阿特柔斯飞船设计院被委任牵头接下来所有M级舰船设计项目，特别是海豚运输船和鼠海豚采矿船的开发。不过该公司把一部分开发工作转包了出去。',
