   description: '灰鲭鲨战斗机是褪色之梦安全防御集团在梅涅劳斯时代设计的第二款飞船。和前一个项目一样，该公司应用了其在褪色之梦星区和Split对抗中获得的经验。开发工作顺利进行两年之后，就在预计于新纪元788年举行的大型发布会的前夕，该公司的灰鲭鲨原型机被来自贫瘠海岸的Boron海盗偷走了。Boron皇家舰队对相关安全问题表达了严重关切并举行了数次听证会。最终，Boron议会针对承包政府项目的企业制定了新的保密条款。根据新规升级安保后，褪色之梦安全防御集团继续开发工作并于新纪元789年成功发布灰鲭鲨战斗机。没人知道被盗的原型机最后怎么样了，因为相关技术并没有外流到其他势力。nn梅涅劳斯时代的飞船生产于新纪元785年到798年之间，是针对星门关闭而开发的第二批高度自动化的飞船。为了减小质量，这些飞船大部分空间填充空气，因此Boron船员需要穿戴防护服。梅涅劳斯的新内阁向中标政府合同的企业开放了多项Boron皇家防御军事研究所新研发的保密技术。采用这些技术设计的飞船不如第一批阿特柔斯时代的飞船结实，但是操控性更佳。',
