   description: '由 Argon Federation 和 Teladi 财政部联合开发的"特使"，整合了各派系的最新技术。"特使"级配备了专属的高性能引擎和护盾生成器，其他船舰无法使用。nn该联合技术计划还包括为"特使"开发一套专用的重型武器。由于市场需求，也推出了这些武器的炮塔变体。这些变体与多种船舰兼容，但由于技术限制，某些船舰除外。该船舰还包括两个前向挂载点，支持一系列传统武器以提供战术灵活性。nn船舰具有专用的低信号姿态，在此姿态下，大多数武器系统会被隐藏且无法操作。在此配置下，船舰的可探测性降低且机动性增强，但代价是牺牲了速度。nn船舰操作员还可以启动派系伪装协议，使船舰在外部观察时显示为属于另一派系。这些先进协议仅以严格的个人基础授权，不提供给受雇人员。',
